public record ShortcutIconOption(
    string Key,
    StreamGeometry? Geometry = null,
    IImage? Image = null,
    bool IsCustom = false)
{
    public StreamGeometry? Icon => Geometry;
    public bool HasImage => Image != null;
    public string DisplayName => Key.StartsWith("custom:", StringComparison.OrdinalIgnoreCase)
        ? Key[7..]
        : Key;
}

public record ShortcutIconCategory(string Name, IReadOnlyList<ShortcutIconOption> Icons);

