    public static readonly ShortcutIconOption[] All =
        Keys.Select(k => new ShortcutIconOption(k, Geometry: Get(k))).ToArray();

    private static readonly Dictionary<string, ShortcutIconOption> OptionsByKey =
        All.ToDictionary(x => x.Key, StringComparer.OrdinalIgnoreCase);

    public static StreamGeometry Get(string key) =>
        Icons.TryGetValue(key, out var geometry) ? geometry : Icons["App"];

    public static ShortcutIconOption FindOption(string? key)
    {
        if (string.IsNullOrEmpty(key)) return OptionsByKey["App"];
        if (OptionsByKey.TryGetValue(key, out var opt)) return opt;
        if (!key.StartsWith("custom:", StringComparison.OrdinalIgnoreCase) && OptionsByKey.TryGetValue($"custom:{key}", out var optCustom))
            return optCustom;
        return OptionsByKey["App"];
    }

