    public static ObservableCollection<ShortcutIconOption> CustomIcons { get; } = [];

    private static readonly string CustomIconsFolder = Path.Combine(Const.CurrentFolder, "CustomIcons");

    static ShortcutIcon()
    {
        LoadCustomIcons();
    }

    public static void LoadCustomIcons()
    {
        try
        {
            if (!Directory.Exists(CustomIconsFolder)) return;

            foreach (var file in Directory.GetFiles(CustomIconsFolder))
            {
                RegisterCustomFile(file);
            }
        }
        catch
        {
        }
    }

    public static ShortcutIconOption? AddCustomIcon(string sourceFilePath)
    {
        try
        {
            if (!File.Exists(sourceFilePath)) return null;

            Directory.CreateDirectory(CustomIconsFolder);
            var fileName = Path.GetFileName(sourceFilePath);
            var destPath = Path.Combine(CustomIconsFolder, fileName);

            if (!string.Equals(Path.GetFullPath(sourceFilePath), Path.GetFullPath(destPath), StringComparison.OrdinalIgnoreCase))
            {
                File.Copy(sourceFilePath, destPath, overwrite: true);
            }

            return RegisterCustomFile(destPath);
        }
        catch
        {
            return null;
        }
    }

    public static void DeleteCustomIcon(string key)
    {
        try
        {
            var opt = CustomIcons.FirstOrDefault(x => string.Equals(x.Key, key, StringComparison.OrdinalIgnoreCase));
            if (opt != null)
            {
                CustomIcons.Remove(opt);
                OptionsByKey.Remove(key);
            }

            var fileName = key.StartsWith("custom:", StringComparison.OrdinalIgnoreCase) ? key[7..] : key;
            var path = Path.Combine(CustomIconsFolder, fileName);
            if (File.Exists(path))
            {
                File.Delete(path);
            }
        }
        catch
        {
        }
    }

    private static ShortcutIconOption? RegisterCustomFile(string filePath)
    {
        try
        {
            var fileName = Path.GetFileName(filePath);
            var key = $"custom:{fileName}";

            var existing = CustomIcons.FirstOrDefault(x => string.Equals(x.Key, key, StringComparison.OrdinalIgnoreCase));
            if (existing != null)
            {
                return existing;
            }

            var ext = Path.GetExtension(filePath).ToLowerInvariant();
            ShortcutIconOption option;

            if (ext == ".svg")
            {
                var geom = TryParseSvgGeometry(filePath);
                if (geom != null)
                {
                    option = new ShortcutIconOption(key, Geometry: geom, IsCustom: true);
                }
                else
                {
                    using var stream = File.OpenRead(filePath);
                    var bmp = new Bitmap(stream);
                    option = new ShortcutIconOption(key, Image: bmp, IsCustom: true);
                }
            }
            else
            {
                using var stream = File.OpenRead(filePath);
                var bmp = new Bitmap(stream);
                option = new ShortcutIconOption(key, Image: bmp, IsCustom: true);
            }

            OptionsByKey[key] = option;
            CustomIcons.Add(option);
            return option;
        }
        catch
        {
            return null;
        }
    }

    private static StreamGeometry? TryParseSvgGeometry(string svgPath)
    {
        try
        {
            var doc = XDocument.Load(svgPath);
            var paths = doc.Descendants()
                .Where(e => e.Name.LocalName.Equals("path", StringComparison.OrdinalIgnoreCase))
                .Select(e => (string?)e.Attribute("d"))
                .Where(d => !string.IsNullOrWhiteSpace(d));

            var combined = string.Join(" ", paths);
            if (!string.IsNullOrWhiteSpace(combined))
            {
                return StreamGeometry.Parse(combined);
            }
        }
        catch
        {
        }
        return null;
    }

    private static IReadOnlyList<ShortcutIconOption> GetOptions(params string[] keys) =>
        keys.Select(FindOption).ToArray();
